  "claim": {
    "component_id": "C013.component",
    "value": "Copied or derivative records are not to be counted as independent corroboration.",
    "scope": "Assessment of corroborative independence, without asserting that such records are necessarily false.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly states the restriction on counting copied or derivative records as independent corroboration."
    }
  },
  "signal_basis": {
    "component_id": "C013.signal_basis",
    "value": "Records are identified as copied or derivative while assessing whether agreement supplies independently originating corroboration.",
    "scope": "The proposed record checks, assuming derivation is correctly identified; no actual findings are asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 supplies the derivation check, P015 supplies the independent-origin criterion, and P018 establishes that these are proposed checks rather than completed observations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C013.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this supported claim."
    }
  },
  "rationale": "Correctly identified copying or derivation establishes dependence for the information reproduced. Agreement attributable to that dependence cannot count as independent corroboration. This restriction does not imply that the records are false.",
  "uncertainty": "The records' truth remains open; it does not affect the bounded independence claim.",
  "anomalies": []
}
